const body = $input.first().json.body || $input.first().json;

const to = body.to;
const subject = body.subject || 'Scout Revenue True-Up Notice';
const message = body.body || '';
const cc = body.cc || '';
const bcc = body.bcc || '';
const senderName = body.senderName || 'Scout RevOps Assurance';
const clientName = body.clientName || '';
const buttonText = body.buttonText || 'View Audit Ledger';
const buttonUrl = body.buttonUrl || '';
const attachments = body.attachments || [];

const htmlBody = `
<!DOCTYPE html>
<html lang="en" style="color-scheme: light !important;" data-force-color-mode="light">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${subject}</title>
  <meta name="color-scheme" content="light">
  <meta name="supported-color-schemes" content="light">
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root { color-scheme: light !important; }
    @media (prefers-color-scheme: dark) {
      html, body { background-color: #f1f5f9 !important; color: #1e293b !important; }
    }
  </style>
</head>
<body style="margin:0; padding:0; background-color:#f1f5f9; font-family: Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f1f5f9; padding: 40px 16px;">
    <tr>
      <td align="center">
        <table width="600" cellpadding="0" cellspacing="0" style="max-width:600px; width:100%; background-color:#ffffff; border-radius:10px; border: 1px solid #e2e8f0; overflow:hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);">
          <tr>
            <td style="padding: 22px 36px; background-color:#0f172a; border-bottom: 1px solid #1e293b;">
              <table cellpadding="0" cellspacing="0" width="100%">
                <tr>
                  <td style="vertical-align:middle;">
                    <div style="display:inline-block; width:10px; height:10px; border-radius:50%; background-color:#6366f1; vertical-align:middle; margin-right:8px;"></div>
                    <span style="color:#ffffff; font-size:15px; font-weight:700; letter-spacing:-0.02em;">Scout</span>
                    <span style="color:#94a3b8; font-size:13px; font-weight:500; margin-left:6px;">Revenue Assurance</span>
                  </td>
                  ${clientName ? `
                  <td align="right" style="vertical-align:middle;">
                    <span style="background-color:rgba(99,102,241,0.2); color:#c7d2fe; font-size:11px; font-weight:600; padding:4px 10px; border-radius:12px;">
                      ${clientName}
                    </span>
                  </td>
                  ` : ''}
                </tr>
              </table>
            </td>
          </tr>
          <tr>
            <td style="padding: 36px 36px 28px;">
              <h1 style="margin: 0 0 18px; color:#0f172a; font-size:19px; font-weight:700; line-height:1.35; letter-spacing:-0.02em;">${subject}</h1>
              <div style="height:1px; background-color:#e2e8f0; margin-bottom:22px;"></div>
              <div style="color:#334155; font-size:14px; font-weight:400; line-height:1.75;">
                ${message.replace(/\n/g, '<br/>')}
              </div>
              ${attachments.length > 0 ? `
              <div style="margin-top:26px; padding:14px 18px; background-color:#f8fafc; border-radius:8px; border: 1px solid #e2e8f0;">
                <p style="margin:0 0 8px; color:#64748b; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:0.06em;">Verified Attachments (${attachments.length})</p>
                ${attachments.map(a => `<p style="margin:4px 0; color:#0f172a; font-size:13px; font-weight:500;">📄 ${a.filename}</p>`).join('')}
              </div>
              ` : ''}
              ${buttonUrl ? `
              <div style="margin-top:32px;">
                <a href="${buttonUrl}" style="display:inline-block; background-color:#4f46e5; color:#ffffff; text-decoration:none; padding:11px 24px; border-radius:6px; font-size:13px; font-weight:600; letter-spacing:-0.01em;">
                  ${buttonText} &rarr;
                </a>
              </div>
              ` : ''}
            </td>
          </tr>
          <tr>
            <td style="padding: 16px 36px; background-color:#f8fafc; border-top: 1px solid #e2e8f0;">
              <table width="100%" cellpadding="0" cellspacing="0">
                <tr>
                  <td style="vertical-align:middle;">
                    <p style="margin:0; color:#64748b; font-size:12px; font-weight:400;">Sent via ${senderName}</p>
                  </td>
                  <td align="right" style="vertical-align:middle;">
                    <span style="color:#94a3b8; font-size:11px;">Automated RevOps Assurance</span>
                  </td>
                </tr>
              </table>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;

function getMimeType(att) {
  if (att.mimeType) return att.mimeType;
  const ext = (att.filename || '').split('.').pop().toLowerCase();
  const mimeMap = {
    'txt':  'text/plain',
    'pdf':  'application/pdf',
    'png':  'image/png',
    'jpg':  'image/jpeg',
    'jpeg': 'image/jpeg',
    'gif':  'image/gif',
    'csv':  'text/csv',
    'json': 'application/json',
    'zip':  'application/zip',
    'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
  };
  return mimeMap[ext] || 'application/octet-stream';
}

const outputItem = {
  json: { to, subject, htmlBody, cc, bcc, attachmentCount: attachments.length },
  ...(attachments.length > 0 ? { binary: {} } : {})
};

if (attachments.length > 0) {
  for (let index = 0; index < attachments.length; index++) {
    const att = attachments[index];
    outputItem.binary[`attachment_${index}`] = await this.helpers.prepareBinaryData(
      Buffer.from(att.content, 'base64'),
      att.filename,
      getMimeType(att)
    );
  }
}

return [outputItem];
